// --- Scoring Logic ---
const scorePrompt = (prompt) => {
  let score = 0;
  let breakdown = [];
  let recommendations = [];
  // This is a simplified scoring logic. A real app might have more complex criteria.
  if (prompt.length > 50) score += 20;
  if (prompt.split(' ').length > 10) score += 20;
  if (prompt.toLowerCase().includes('generate') || prompt.toLowerCase().includes('analyze')) score += 15;
  if (prompt.toLowerCase().includes('table') || prompt.toLowerCase().includes('list')) score += 15;
  if (prompt.toLowerCase().includes('as a')) score += 10;
  if (prompt.match(/\d+/g)) score += 10;
  score += Math.floor(Math.random() * 11); // Add a bit of randomness
  score = Math.min(score, 100); // Cap score at 100

  breakdown.push({ criteria: 'Clarity & Specificity', score: Math.min(score, 30), max: 30 });
  breakdown.push({ criteria: 'Context', score: Math.min(Math.max(0, score-30), 25), max: 25 });
  breakdown.push({ criteria: 'Constraints & Format', score: Math.min(Math.max(0, score-55), 20), max: 20 });
  breakdown.push({ criteria: 'Persona-Task Alignment', score: Math.min(Math.max(0, score-75), 15), max: 15 });
  breakdown.push({ criteria: 'Action Verb Usage', score: Math.min(Math.max(0, score-90), 10), max: 10 });
  
  if (score < 80) recommendations.push("Try to be more specific about the desired output format.");
  if (score < 60) recommendations.push("Add more context about your role or the situation.");

  return { totalScore: score, breakdown, recommendations };
};

