// --- Main App Component ---
export default function App() {
  const [appState, setAppState] = useState('user-info'); // user-info, persona-selection, prompt-challenge, results
  const [userInfo, setUserInfo] = useState(null);
  const [selectedPersona, setSelectedPersona] = useState(null);
  const [currentChallenge, setCurrentChallenge] = useState(null);
  const [leaderboardScores, setLeaderboardScores] = useState([]);
  const [authReady, setAuthReady] = useState(false);
  
  const appId = typeof __app_id !== 'undefined' ? __app_id : 'default-app-id';
  const leaderboardCollectionPath = `artifacts/${appId}/public/data/leaderboard`;

  useEffect(() => {
    // Authenticate user
    const authenticate = async () => {
        onAuthStateChanged(auth, async (user) => {
            if (user) {
                setAuthReady(true);
            } else {
                try {
                    if (typeof __initial_auth_token !== 'undefined' && __initial_auth_token) {
                        await signInWithCustomToken(auth, __initial_auth_token);
                    } else {
                        await signInAnonymously(auth);
                    }
                    setAuthReady(true);
                } catch (error) {
                    console.error("Authentication failed:", error);
                }
            }
        });
    };
    authenticate();
  }, []);

  useEffect(() => {
    if (!authReady) return;

    // Set up Firestore listener for leaderboard
    const q = query(collection(db, leaderboardCollectionPath), orderBy("score", "desc"), limit(10));
    const unsubscribeFirestore = onSnapshot(q, (querySnapshot) => {
      const scores = [];
      querySnapshot.forEach((doc) => {
        scores.push({ id: doc.id, ...doc.data() });
      });
      setLeaderboardScores(scores);
    }, (error) => {
        console.error("Snapshot listener error:", error);
    });

    return () => unsubscribeFirestore();
  }, [authReady, leaderboardCollectionPath]);

  const handleStart = (info) => {
    setUserInfo(info);
    setAppState('persona-selection');
  };
  
  const handleSelectPersona = (personaKey) => {
    setSelectedPersona(personaKey);
    const challenges = personaData[personaKey].challenges;
    const randomChallenge = challenges[Math.floor(Math.random() * challenges.length)];
    setCurrentChallenge(randomChallenge);
    setAppState('prompt-challenge');
  };

  const handleSubmitPrompt = async (prompt, results) => {
    // Save score to Firestore
    try {
        await addDoc(collection(db, leaderboardCollectionPath), {
            name: userInfo.name,
            company: userInfo.company,
            score: results.totalScore,
            persona: personaData[selectedPersona].name,
            timestamp: new Date()
        });
    } catch (e) {
        console.error("Error adding document: ", e);
    }
    setAppState('results');
    // Store results locally to display them
    window.tempResults = { challenge: currentChallenge, prompt, results };
  };

  const handleRestart = () => {
    setAppState('persona-selection');
    setSelectedPersona(null);
    setCurrentChallenge(null);
  };
  
  const handleBackToPersonas = () => {
      setAppState('persona-selection');
  };

  const renderContent = () => {
    switch (appState) {
      case 'user-info':
        return <UserInfoForm onStart={handleStart} />;
      case 'persona-selection':
        return <PersonaSelector onSelectPersona={handleSelectPersona} />;
      case 'prompt-challenge':
        return <PromptChallenge persona={selectedPersona} challenge={currentChallenge} onBack={handleBackToPersonas} onSubmit={handleSubmitPrompt} />;
      case 'results':
        const { challenge, prompt, results } = window.tempResults || { challenge: null, prompt: '', results: { totalScore: 0, breakdown: [], recommendations: [] } };
        return <Results challenge={challenge} prompt={prompt} results={results} onRestart={handleRestart} leaderboardScores={leaderboardScores} />;
      default:
        return <UserInfoForm onStart={handleStart} />;
    }
  };

  return (
    <div className="bg-gray-50 min-h-screen font-sans p-4 sm:p-6 md:p-8">
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in { animation: fadeIn 0.5s ease-out forwards; }
      `}</style>
      <main>
        {authReady ? renderContent() : <div className="text-center text-gray-500">Connecting...</div>}
      </main>
      <footer className="text-center mt-12 pb-4">
        <p className="text-gray-500 text-sm">A Prompt Engineering Tool by Gemini</p>
      </footer>
    </div>
  );
}
